import{_ as a,o as i,c as t,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Technical plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/campaign-timeline/plan.md","filePath":"feature/campaign-timeline/plan.md"}'),n={name:"feature/campaign-timeline/plan.md"};function r(l,e,s,d,c,p){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="technical-plan" tabindex="-1">Technical plan <a class="header-anchor" href="#technical-plan" aria-label="Permalink to &quot;Technical plan&quot;">​</a></h1><ol><li>Add additive planning fields and backwards-compatible DTO constructors. Default only newly created records. Introduce scoped batched timeline response; reuse workflow policy and member validation. Revision-checked schedule updates never write Post/publish fields. Embedded subtask writes use parent revision/CAS.</li><li>Web feature files under pages/campaign/{components,hooks,services,types,utils}; keep orchestrator short. Query timeline once (no row request waterfall), reuse TaskWorkflowContent and existing subtask UI in Task dialog. Reuse deployment/closure components without changing publish.</li><li>Serialized Campaign field saves and query invalidation; row scheduling uses current server revision and rollback on failure. Filters preserve hierarchy. Pointer capture for drag and column resize, keyboard alternatives; derive view bounds independently from Campaign.</li><li>Locale changes: src/i18n/locales/vi/campaign.json and en/campaign.json. Semantic colors, existing primitives, no React Bits dependency required for a data-dense timeline.</li><li>Add Mongo migration in docs/database/migrations; merge optional date validator properties into init; update TaskSampleSeeder. Do not APPLY shared DB or touch unrelated Post validators.</li><li>Run Web CI and relevant backend tests/build. Keep newly authored test artifacts outside src and uncommitted local-only. Validate light/dark, keyboard, 375/768/1440, filters, continuous creation, revision conflicts, default timezone and free dates.</li></ol><h2 id="layout-refinement" tabindex="-1">Layout refinement <a class="header-anchor" href="#layout-refinement" aria-label="Permalink to &quot;Layout refinement&quot;">​</a></h2><ol><li>Add a viewport sizing hook and right-rail plan editor, preserve field-level auto-save and unsaved gating.</li><li>Extract interactive milestone rail with local draft/version, preview, direct create/edit, error retry and keyboard support. Reuse Campaign update API.</li><li>Correct calendar scale to match actual lane width, add fit zoom, clearer date ruler and vertical borders; add direct unscheduled range preview.</li><li>Update campaign vi/en locales and CSS only within feature. Test real React components with intercepted API, no shared DB writes.</li></ol><h2 id="simplification-implementation" tabindex="-1">Simplification implementation <a class="header-anchor" href="#simplification-implementation" aria-label="Permalink to &quot;Simplification implementation&quot;">​</a></h2><p>Move Campaign date fields to a compact timeline toolbar; keep strategy as a right-rail disclosure. Enforce persisted-width minima and minimum daily pixel scale. Use Campaign bounds without decorative padding/today extension; preserve actual out-of-bounds task visibility and free scheduling. Add explicit boundary guides and synchronized, keyboard-accessible custom horizontal scrollbar. Direct click uses existing revision-checked schedule API. Update only Campaign feature and parallel campaign locales.</p><p>Date/column correction: repair open-ended range fallback; measure translated status labels with the current font; derive safe column widths, version local layout preferences; add truncated heading wrappers; retain one synchronized scroll control and horizontal wheel support. Test mock cases plus the user-provided local Campaign page without modifying Campaign data.</p><h2 id="milestone-drag-—-2026-11-07" tabindex="-1">Milestone drag — 2026-11-07 <a class="header-anchor" href="#milestone-drag-—-2026-11-07" aria-label="Permalink to &quot;Milestone drag — 2026-11-07&quot;">​</a></h2><p>Extend TimelineMilestoneRail with pointer capture, drag threshold, local preview and click suppression. Reuse existing versioned milestone submit/error handling; no API/DB changes. Add campaign.timeline.moveMilestone in vi/en campaign.json and scoped cursor/touch CSS.</p><h2 id="inclusive-deadline-display-—-2026-11-07" tabindex="-1">Inclusive deadline display — 2026-11-07 <a class="header-anchor" href="#inclusive-deadline-display-—-2026-11-07" aria-label="Permalink to &quot;Inclusive deadline display — 2026-11-07&quot;">​</a></h2><p>Use inclusive day-cell width for scheduled and unscheduled previews; unscheduled drag stores the last selected day instead of an exclusive next day (retain existing API start&lt;end requirement). Remove Task drag label/title and milestone drag date span, keep milestone create/editor day context. No DB migration.</p><h2 id="compact-timeline-controls-—-2026-11-07" tabindex="-1">Compact timeline controls — 2026-11-07 <a class="header-anchor" href="#compact-timeline-controls-—-2026-11-07" aria-label="Permalink to &quot;Compact timeline controls — 2026-11-07&quot;">​</a></h2><p>Update CampaignTimelineGrid default scale/week and replace native Select with shared DropdownMenu radio group; remove Fit affordances. Render milestone date picker only when editing an existing milestone. No API/DB change.</p><h3 id="scale-selection-highlight" tabindex="-1">Scale selection highlight <a class="header-anchor" href="#scale-selection-highlight" aria-label="Permalink to &quot;Scale selection highlight&quot;">​</a></h3><p>Scope indicator hiding and compact left padding to timeline scale RadioItem classes; do not change shared DropdownMenu behavior.</p><h2 id="compact-multiple-filters-—-2026-11-07" tabindex="-1">Compact multiple filters — 2026-11-07 <a class="header-anchor" href="#compact-multiple-filters-—-2026-11-07" aria-label="Permalink to &quot;Compact multiple filters — 2026-11-07&quot;">​</a></h2><p>Change TimelineFilters assignee/supervisor to string arrays; update EMPTY_FILTERS, matchesTimeline, Grid filtered flag and FilterBar toggles. Replace people single native select with checkbox choices, remove chips construction/rendering. Existing locale keys reused, semantic theme colors.</p><h2 id="remove-duplicate-bottom-information-—-2026-11-07" tabindex="-1">Remove duplicate bottom information — 2026-11-07 <a class="header-anchor" href="#remove-duplicate-bottom-information-—-2026-11-07" aria-label="Permalink to &quot;Remove duplicate bottom information — 2026-11-07&quot;">​</a></h2><p>Remove Grid anchor/footer markup and dead scrollToDay helper, remove scrollbar caption but preserve its grid inset, delete unused scoped anchor/caption CSS.</p><h2 id="toolbar-order-—-2026-11-07" tabindex="-1">Toolbar order — 2026-11-07 <a class="header-anchor" href="#toolbar-order-—-2026-11-07" aria-label="Permalink to &quot;Toolbar order — 2026-11-07&quot;">​</a></h2><p>Reorder existing Grid toolbar JSX; remove filter rounded-top class since it is no longer the top row. No behavior/API/i18n changes.</p><h2 id="view-controls-in-filter-row-—-2026-11-07" tabindex="-1">View controls in filter row — 2026-11-07 <a class="header-anchor" href="#view-controls-in-filter-row-—-2026-11-07" aria-label="Permalink to &quot;View controls in filter row — 2026-11-07&quot;">​</a></h2><p>Add optional trailingControls ReactNode slot to TimelineFilterBar; pass existing Today/scale JSX from Grid. No control behavior/state/API changes.</p><h2 id="personal-work-dropdown-styling-—-2026-11-07" tabindex="-1">Personal-work dropdown styling — 2026-11-07 <a class="header-anchor" href="#personal-work-dropdown-styling-—-2026-11-07" aria-label="Permalink to &quot;Personal-work dropdown styling — 2026-11-07&quot;">​</a></h2><p>Reuse shared DropdownMenu components in TimelineFilterBar for mine filter only. Existing Select remains for other popover fields. Match scale menu styling, compact trigger and full option labels; no data/API changes.</p><h2 id="filter-checkbox-layout-—-2026-11-07" tabindex="-1">Filter checkbox layout — 2026-11-07 <a class="header-anchor" href="#filter-checkbox-layout-—-2026-11-07" aria-label="Permalink to &quot;Filter checkbox layout — 2026-11-07&quot;">​</a></h2><p>Set checkbox Input wrapperClassName w-auto shrink-0 and content span min-w-0 flex-1 break-words. Set popover right column minmax(0,1fr)/min-w-0. Keep native label-click/keyboard and multi-filter behavior.</p><h2 id="deliverable-choices-and-filter-audit-—-2026-11-07" tabindex="-1">Deliverable choices and filter audit — 2026-11-07 <a class="header-anchor" href="#deliverable-choices-and-filter-audit-—-2026-11-07" aria-label="Permalink to &quot;Deliverable choices and filter audit — 2026-11-07&quot;">​</a></h2><p>Change TimelineFilters deliverable to string[], update defaults, matcher and Grid filtered flag. Replace FilterBar native deliverable Select with checkbox list and schedule Select with radio list; remove unused Select import. Wrap sidebar labels in variable-height buttons. Reuse vi/en strings and Input wrapper sizing.</p><h2 id="compact-popup-width-—-2026-11-07" tabindex="-1">Compact popup width — 2026-11-07 <a class="header-anchor" href="#compact-popup-width-—-2026-11-07" aria-label="Permalink to &quot;Compact popup width — 2026-11-07&quot;">​</a></h2><p>Adjust FilterBar popup width/grid/sidebar button classes only. Category labels nowrap/truncate, accessible full text/title. Existing state and filter semantics unchanged.</p><h2 id="optional-strategy-and-selected-package-navigation-—-2026-11-07" tabindex="-1">Optional strategy and selected-package navigation — 2026-11-07 <a class="header-anchor" href="#optional-strategy-and-selected-package-navigation-—-2026-11-07" aria-label="Permalink to &quot;Optional strategy and selected-package navigation — 2026-11-07&quot;">​</a></h2><p>Remove strategy predicate from MediaCampaignServiceImpl.validateApprovalPlan and DeploymentPanel conditions; derive readiness denominator from condition length. Change Sidebar/Layout navigation gate from approval to missing workspaceMediaPackageId. Check stored package selection updates existing store. No schema/API changes.</p>',33)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
